<?php $pageTitle=page_title('Content moderation'); $page='admin-moderation'; ?>
<div class="dashboard-head reveal"><div><span class="eyebrow">Trust & safety</span><h1>Moderation</h1><p>Hide inappropriate content, restore mistakes, and review support messages.</p></div><a class="btn btn-light" href="<?= e(url('admin-users')) ?>"><?= icon('users') ?> User controls</a></div>
<div class="content-card card"><div class="content-head"><div><h2>Active product listings</h2><p>Review currently published listings and hide content that violates marketplace guidelines.</p></div><span class="pill"><?= count($activeProducts) ?></span></div><?php if($activeProducts): ?><div class="table-wrap"><table><thead><tr><th>Product</th><th>Farmer</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($activeProducts as $product): ?><tr><td><strong><?= e($product['name']) ?></strong><br><small class="text-muted"><?= e($product['category_name']) ?></small></td><td><?= e($product['stall_name']) ?></td><td><?= status_pill($product['status']) ?></td><td><form method="post" action="<?= e(url('admin-moderation')) ?>" style="display:flex;gap:6px"><?= csrf_field() ?><input type="hidden" name="type" value="product"><input type="hidden" name="content_id" value="<?= (int)$product['id'] ?>"><input type="text" name="reason" maxlength="500" placeholder="Reason" required style="min-width:150px;min-height:36px"><button class="btn btn-danger btn-sm" type="submit" name="action" value="hide">Hide</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="text-muted">No active listings to review.</p><?php endif; ?></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Hidden product listings</h2><p>Soft-hidden products disappear publicly while order history remains intact.</p></div><span class="pill pill-red"><?= count($products) ?></span></div><?php if($products): ?><div class="table-wrap"><table><thead><tr><th>Product</th><th>Farmer</th><th>Category</th><th>Price</th><th>Updated</th><th>Moderation</th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><div class="table-product"><span class="table-thumb"><?= e(product_placeholder($product['category_name'])) ?></span><div><strong><?= e($product['name']) ?></strong><br><small class="text-muted"><?= e($product['description']) ?></small></div></div></td><td><?= e($product['stall_name']) ?><br><small class="text-muted"><?= e($product['farmer_name']) ?></small></td><td><?= e($product['category_name']) ?></td><td><?= money($product['price']) ?></td><td><?= format_date($product['updated_at'],'M j, Y') ?></td><td><form method="post" action="<?= e(url('admin-moderation')) ?>" style="display:grid;gap:6px;min-width:210px"><?= csrf_field() ?><input type="hidden" name="type" value="product"><input type="hidden" name="content_id" value="<?= (int)$product['id'] ?>"><input type="text" name="reason" maxlength="500" placeholder="Reason (required to hide)" required style="min-height:38px"><button class="btn btn-light btn-sm" type="submit" name="action" value="restore"><?= icon('check') ?> Restore listing</button><button class="btn btn-danger btn-sm" type="submit" name="action" value="hide">Hide / update reason</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">✅</span><h3>No hidden product listings</h3><p>The public product catalog is clear.</p></div><?php endif; ?></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Published reviews</h2><p>Review a recent customer comment before deciding whether it should remain public.</p></div><span class="pill"><?= count($activeReviews) ?></span></div><?php if($activeReviews): ?><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Product</th><th>Rating</th><th>Comment</th><th>Action</th></tr></thead><tbody><?php foreach($activeReviews as $review): ?><tr><td><?= e($review['customer_name']) ?></td><td><?= e($review['product_name']) ?></td><td><?= star_display((float)$review['rating']) ?></td><td style="max-width:360px"><?= e($review['comment']) ?></td><td><form method="post" action="<?= e(url('admin-moderation')) ?>" style="display:flex;gap:6px"><?= csrf_field() ?><input type="hidden" name="type" value="review"><input type="hidden" name="content_id" value="<?= (int)$review['id'] ?>"><input type="text" name="reason" maxlength="500" placeholder="Reason" required style="min-width:140px;min-height:36px"><button class="btn btn-danger btn-sm" type="submit" name="action" value="hide">Hide</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="text-muted">No published reviews to review.</p><?php endif; ?></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Hidden reviews</h2><p>Restore a review only when it follows community guidelines.</p></div><span class="pill pill-red"><?= count($reviews) ?></span></div><?php if($reviews): ?><div class="review-grid"><?php foreach($reviews as $review): ?><article class="card review-card"><div class="review-head"><span class="user-avatar"><?= e(initials($review['customer_name'])) ?></span><div><strong><?= e($review['customer_name']) ?></strong><time><?= e($review['product_name']) ?></time></div><span style="margin-left:auto"><?= star_display((float)$review['rating'],false) ?></span></div><p><?= e($review['comment']) ?></p><form class="mt-3" method="post" action="<?= e(url('admin-moderation')) ?>"><?= csrf_field() ?><input type="hidden" name="type" value="review"><input type="hidden" name="content_id" value="<?= (int)$review['id'] ?>"><input type="text" name="reason" maxlength="500" placeholder="Reason (required to hide)" required style="min-height:38px"><div style="display:flex;gap:7px;margin-top:7px"><button class="btn btn-light btn-sm" type="submit" name="action" value="restore">Restore</button><button class="btn btn-danger btn-sm" type="submit" name="action" value="hide">Hide</button></div></form></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">✅</span><h3>No hidden reviews</h3><p>Published ratings currently meet community guidelines.</p></div><?php endif; ?></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Contact inbox</h2><p>Latest support and concern messages from the public contact form.</p></div><span class="pill"><?= count($messages) ?></span></div><?php if($messages): ?><div class="table-wrap"><table><thead><tr><th>Received</th><th>Sender</th><th>Subject</th><th>Message</th><th>Status</th></tr></thead><tbody><?php foreach($messages as $message): ?><tr><td><?= format_date($message['created_at'],'M j, g:i A') ?></td><td><?= e($message['name']) ?><br><small class="text-muted"><?= e($message['email']) ?></small></td><td><?= e($message['subject']) ?></td><td style="max-width:420px"><?= e($message['message']) ?></td><td><?= status_pill($message['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="text-muted">No support messages yet.</p><?php endif; ?></div>
